/** @generate-class-entries */

namespace QFont {
    enum Weight: int
    {
        case THIN = 100;
        case EXTRA_LIGHT = 200;
        case LIGHT = 300;
        case NORMAL = 400;
        case MEDIUM = 500;
        case DEMI_BOLD = 600;
        case BOLD = 700;
        case EXTRA_BOLD = 800;
        case BLACK = 900;
    }
}

namespace QFontDatabase {
    enum SystemFont: int
    {
        case GENERAL_FONT = 0;
        case FIXED_FONT = 1;
        case TITLE_FONT = 2;
        case SMALLEST_READABLE_FONT = 3;
    }
}

namespace QClipboard {
    /** Generated by scripts/gen-enum.php from qclipboard.h (LastMode, an alias of FIND_BUFFER, left out). */
    enum Mode: int
    {
        case CLIPBOARD = 0;
        case SELECTION = 1;
        case FIND_BUFFER = 2;
    }
}

namespace QImage {
    /** The QImage::Format layouts with 8 bits a channel. */
    enum Format: int
    {
        case RGB32 = 4;
        case ARGB32 = 5;
        case ARGB32_PREMULTIPLIED = 6;
        case RGB888 = 13;
        /** Four bytes, red first; the fourth is ignored: opaque. */
        case RGBX8888 = 16;
        case RGBA8888 = 17;
        case RGBA8888_PREMULTIPLIED = 18;
        case BGR888 = 29;
    }
}

namespace QTreeWidgetItem {
    enum ChildIndicatorPolicy: int
    {
        case SHOW_INDICATOR = 0;
        case DONT_SHOW_INDICATOR = 1;
        case DONT_SHOW_INDICATOR_WHEN_CHILDLESS = 2;
    }
}

