        /** Read from the item's tree: false while no tree holds it. */
        public function isExpanded(): bool {}

        public function setExpanded(bool $expand): void {}

        public function childIndicatorPolicy(): QTreeWidgetItem\ChildIndicatorPolicy {}

        public function setChildIndicatorPolicy(QTreeWidgetItem\ChildIndicatorPolicy $policy): void {}
